import{_ as a,o as t,c as r,ag as n}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Panneau /nay","description":"","frontmatter":{},"headers":[],"relativePath":"fr/nay-lib/panel.md","filePath":"fr/nay-lib/panel.md"}'),o={name:"fr/nay-lib/panel.md"};function d(s,e,i,l,u,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="panneau-nay" tabindex="-1">Panneau /nay <a class="header-anchor" href="#panneau-nay" aria-label="Permalink to &quot;Panneau /nay&quot;">​</a></h1><p>Tapez <code>/nay</code> en jeu pour ouvrir le panneau de réglages. Vous voyez chaque script Nayretis que vous avez le droit de configurer. Les joueurs qui ont <code>nay.admin</code> voient aussi la section <strong>Serveur</strong> : la page Nayretis, Permissions, API, Webhooks et Journal.</p><p>Les réglages sont enregistrés dans la base. Quand vous appuyez sur <strong>Enregistrer</strong>, la nouvelle valeur est vérifiée, enregistrée, écrite dans le <a href="/fr/nay-lib/audit">journal</a> et appliquée tout de suite à tous les joueurs connectés. Aucun redémarrage.</p><p>Certaines pages de scripts ont aussi des boutons d&#39;action, comme <strong>Gérer les tunnels</strong> sur la page Car Wash.</p><h2 id="reglages-nayretis" tabindex="-1">Réglages Nayretis <a class="header-anchor" href="#reglages-nayretis" aria-label="Permalink to &quot;Réglages Nayretis&quot;">​</a></h2><p>La page <strong>Nayretis</strong> regroupe les réglages communs à tous les scripts.</p><p>La colonne <strong>Dans /nay</strong> donne le nom affiché dans le panneau. La clé est le nom utilisé par <code>config.lua</code> et par l&#39;<a href="/fr/nay-lib/api">API HTTP</a>.</p><table tabindex="0"><thead><tr><th>Dans /nay</th><th>Clé</th><th>Type</th><th>Défaut</th><th>Description</th></tr></thead><tbody><tr><td>Langue</td><td><code>Locale</code></td><td>langue</td><td>anglais, ou la valeur de <code>nay:locale</code></td><td>Langue de tous les scripts Nayretis : anglais, français, espagnol, portugais, polonais ou allemand.</td></tr><tr><td>Thème de l&#39;interface</td><td><code>Theme</code></td><td><code>graphite</code> ou <code>papier</code></td><td><code>graphite</code></td><td>Apparence des interfaces Nayretis : sombre (Graphite) ou claire (Papier).</td></tr><tr><td>API HTTP</td><td><code>ApiEnabled</code></td><td>oui / non</td><td>non</td><td>Active l&#39;<a href="/fr/nay-lib/api">API HTTP</a>. Tant qu&#39;elle est désactivée, chaque route répond <code>503 api_disabled</code>.</td></tr><tr><td>Taille maximale d&#39;une requête (Ko)</td><td><code>ApiMaxBodyKb</code></td><td>nombre, 1 à 10240</td><td>1024</td><td>Plus grand corps de requête accepté par l&#39;API, en Ko.</td></tr><tr><td>Conservation du journal (jours)</td><td><code>AuditRetentionDays</code></td><td>nombre, 0 à 3650</td><td>90</td><td>Les lignes du journal plus anciennes sont supprimées chaque jour. 0 garde tout.</td></tr></tbody></table><h2 id="qui-peut-ouvrir-le-panneau" tabindex="-1">Qui peut ouvrir le panneau <a class="header-anchor" href="#qui-peut-ouvrir-le-panneau" aria-label="Permalink to &quot;Qui peut ouvrir le panneau&quot;">​</a></h2><ul><li><code>nay.admin</code> donne tout.</li><li><code>nay.config</code> donne les réglages de tous les scripts.</li><li><code>nay.audit</code> ouvre le panneau sur le journal.</li><li><code>&lt;resource&gt;.config</code> donne les réglages d&#39;un script, par exemple <code>nay_car_wash.config</code>.</li></ul><p>Voir <a href="/fr/nay-lib/permissions">Permissions</a> pour les accorder.</p>',11)])])}const h=a(o,[["render",d]]);export{g as __pageData,h as default};
